[[], ["i]\n    \n    # Check if this is the line that raises ConfigError\n    if 'raise ConfigError(' in line and i > 0:\n        # Check if we're in the validation section\n        context = ''.join(lines[max(0, i-6):i])\n        if 'if not result.is_valid:' in context:\n            # Get the indentation\n            indent = len(line) - len(line.lstrip())\n            indent_str = ' ' * indent\n            \n            # Add comment\n            new_lines.append(indent_str + '# Only raise error in strict mode\n')\n            new_lines.append(indent_str + 'if strict:\\n')\n            # Add the raise line\n            new_lines.append(line)\n            # Add the next 3 lines (the f-string)\n            for j in range(1, 4):\n                new_lines.append(lines[i + j])\n            i += 4\n            # Add the else block\n            new_lines.append(indent_str + 'else:\\n')\n            new_lines.append(indent_str + '    # In warn mode, just log the error and continue\\n')\n            new_lines.append(indent_str + '    logger.warning({\\n')\n            new_lines.append(indent_str + '        \"msg\": \"Configuration validation failed - system may not function correctly\",\\n')\n            new_lines.append(indent_str + '        \"errors\": result.errors,\\n')\n            new_lines.append(indent_str + '        \"warnings\": result.warnings,\\n')\n            new_lines.append(indent_str + '        \"missing_required\": result.missing_required,\\n')\n            new_lines.append(indent_str + '        \"note\": \"Set KE_VALIDATE_CONFIG=strict to fail on validation errors\"\\n')\n            new_lines.append(indent_str + '    })\\n')\n            continue\n    \n    new_lines.append(line)\n    i += 1\n\n# Write the file back\nwith open('knowledge_engine/__init__.py', 'w', encoding='utf-8') as f:\n    f.writelines(new_lines)\n\nprint('Fixed configuration validation in __init__.py')"]]